#include "Data/AetherSkillEffectTypes.h"
namespace { bool NN(double V){return FMath::IsFinite(V)&&V>=0.0;} }
bool FAetherDataSkillDefinition::IsStructurallyValid(FString& E) const { E.Reset(); if(DefinitionID.TrimStartAndEnd().IsEmpty()||DisplayName.TrimStartAndEnd().IsEmpty()){E=TEXT("Skill ID and DisplayName are required.");return false;} if(RequiredLevel<=0||!NN(CastTimeSeconds)||!NN(CooldownSeconds)||!NN(Range)||!NN(Radius)||Range<=0.0||Cost.Mana<0||Cost.Health<0||Cost.Resource<0){E=TEXT("Skill level, timing, range or cost is invalid.");return false;} if(Delivery==EAetherSkillDelivery::Area&&Radius<=0.0){E=TEXT("Area skill requires positive radius.");return false;} return true; }
bool FAetherEffectDefinition::IsStructurallyValid(FString& E) const { E.Reset(); if(DefinitionID.TrimStartAndEnd().IsEmpty()||DisplayName.TrimStartAndEnd().IsEmpty()){E=TEXT("Effect ID and DisplayName are required.");return false;} if(!NN(DurationSeconds)||!NN(TickIntervalSeconds)||!FMath::IsFinite(Magnitude)||!FMath::IsFinite(SecondaryMagnitude)||MaxStacks<=0){E=TEXT("Effect duration, magnitude or stacks is invalid.");return false;} if(TickIntervalSeconds>0.0&&DurationSeconds<=0.0){E=TEXT("Ticking effect requires positive duration.");return false;} return true; }
bool FAetherStatusDefinition::IsStructurallyValid(FString& E) const { E.Reset(); if(DefinitionID.TrimStartAndEnd().IsEmpty()||DisplayName.TrimStartAndEnd().IsEmpty()){E=TEXT("Status ID and DisplayName are required.");return false;} if(EffectIDs.Num()==0){E=TEXT("Status requires at least one effect.");return false;} return true; }
